const ALNUM = /^[A-Za-z0-9]$/;
const WS = /\s/;
const ESCAPABLE = new Set(["*", "_", "`", "\\"]);

/** R1: escape `&`, `<` and `>`; every other character is copied unchanged. */
function escapeHtml(text) {
	return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

/**
 * Find the closer of a `*` or `_` span opened at `open`.
 * A candidate is the first later marker of the same kind whose previous
 * character is not whitespace and which is not the character right after
 * the opener. For `_`, the following character must be end-of-text or not a
 * letter/digit. Escaped markers are skipped, and complete code spans are
 * skipped over so a marker inside one can never be the closer.
 * Returns -1 when there is no valid closer.
 */
function findCloser(text, open, kind) {
	const n = text.length;
	let j = open + 2;
	while (j < n) {
		const ch = text[j];
		if (ch === "\\") {
			// R7: `\` + escapable char is plain text; the char is not a marker.
			j += j + 1 < n && ESCAPABLE.has(text[j + 1]) ? 2 : 1;
			continue;
		}
		if (ch === "`") {
			const next = text.indexOf("`", j + 1);
			// Skip a complete code span (R5); adjacent `` and lone ` are plain text.
			if (next !== -1 && next !== j + 1) j = next + 1;
			else j += 1;
			continue;
		}
		if (ch === kind && !WS.test(text[j - 1])) {
			if (kind === "*") return j;
			// R4: `_` closes only if followed by end-of-text or a non-alphanumeric.
			const after = j + 1 < n ? text[j + 1] : "";
			if (!ALNUM.test(after)) return j;
		}
		j += 1;
	}
	return -1;
}

/** Render one region of text with the full markup rules. */
function renderSpan(text) {
	const n = text.length;
	let out = "";
	let i = 0;
	while (i < n) {
		const ch = text[i];
		if (ch === "\\") {
			// R7: drop the backslash, emit the next char as plain text.
			const next = i + 1 < n ? text[i + 1] : "";
			if (ESCAPABLE.has(next)) {
				out += escapeHtml(next);
				i += 2;
			} else {
				out += escapeHtml(ch);
				i += 1;
			}
			continue;
		}
		if (ch === "*" || ch === "_") {
			const prev = i > 0 ? text[i - 1] : "";
			// R3: the char right after must exist and be non-whitespace.
			// R4: `_` additionally needs a non-alphanumeric (or start) before it.
			const mayOpen =
				i + 1 < n && !WS.test(text[i + 1]) && (ch === "*" || !ALNUM.test(prev));
			if (mayOpen) {
				const close = findCloser(text, i, ch);
				if (close !== -1) {
					const tag = ch === "*" ? "b" : "i";
					// R6: the content is rendered by the same rules.
					out += `<${tag}>${renderSpan(text.slice(i + 1, close))}</${tag}>`;
					i = close + 1;
					continue;
				}
			}
			out += escapeHtml(ch);
			i += 1;
			continue;
		}
		if (ch === "`") {
			const close = text.indexOf("`", i + 1);
			if (close === i + 1) {
				// R5: two adjacent backticks are plain text, as two backticks.
				out += escapeHtml("``");
				i += 2;
				continue;
			}
			if (close !== -1) {
				// R5: only R1 escaping applies inside a code span.
				out += `<code>${escapeHtml(text.slice(i + 1, close))}</code>`;
				i = close + 1;
				continue;
			}
			// No later backtick: plain text.
			out += escapeHtml(ch);
			i += 1;
			continue;
		}
		out += escapeHtml(ch);
		i += 1;
	}
	return out;
}

/**
 * Render a small markup language to an HTML string.
 * `*x*` -> <b>, `_x_` -> <i>, `` `x` `` -> <code>.
 *
 * @param {string} text
 * @returns {string}
 */
export function render(text) {
	if (typeof text !== "string") {
		throw new TypeError("text must be a string");
	}
	return renderSpan(text);
}

